namespace CodebaseReviewTool.Core.Data.Entities;

/// <summary>Cached Azure DevOps pull request metadata.</summary>
public class PullRequest
{
    /// <summary>The DevOps pull request id (unique within the organisation); not generated by the database.</summary>
    public int Id { get; set; }

    public string RepositoryKey { get; set; } = string.Empty;

    public string Title { get; set; } = string.Empty;

    public string Description { get; set; } = string.Empty;

    public string AuthorName { get; set; } = string.Empty;

    public string SourceBranch { get; set; } = string.Empty;

    public string TargetBranch { get; set; } = string.Empty;

    public string SourceCommit { get; set; } = string.Empty;

    /// <summary>DevOps status text (e.g. <c>active</c>, <c>completed</c>, <c>abandoned</c>).</summary>
    public string Status { get; set; } = string.Empty;

    /// <summary>UTC.</summary>
    public DateTime CreatedAt { get; set; }

    public string Url { get; set; } = string.Empty;

    /// <summary>UTC time the poller last saw this PR.</summary>
    public DateTime LastSeenAt { get; set; }

    public bool IsOpen { get; set; }

    public List<Review> Reviews { get; set; } = [];
}
